mapper.select:
SELECT p.code, p.name, p.value, p.param_type AS paramType, p.value_range AS valueRange, p.description, p.deployment_standard AS deploymentStandard, s.software, s.title AS standardTitle, s.version AS standardVersion, s.published_at AS publishedAt FROM standard_parameters p JOIN parameter_standards s ON s.id = p.parameter_standard_id WHERE p.active = 1 AND s.status = 'PUBLISHED'
AND s.software = #{software}
AND (p.code = #{name} OR p.name = #{name} OR p.code LIKE CONCAT('%', #{name}, '%') OR p.name LIKE CONCAT('%', #{name}, '%'))
ORDER BY CASE WHEN p.code = #{name} OR p.name = #{name} THEN 0 ELSE 1 END, p.code LIMIT #{limit}
